mapper.insert:
insert into governance.audit_log (
    id, actor_id, actor_type, action, target_type, target_id,
    before_data, after_data, client_ip, user_agent, correlation_id, trace_id
) values (
    #{id}, #{actorId}, #{actorType}, #{action}, #{targetType}, #{targetId},
    cast(#{beforeData} as jsonb), cast(#{afterData} as jsonb), #{clientIp}, #{userAgent}, #{correlationId}, #{traceId}
)

mapper.select:
select id, actor_id, actor_type, action, target_type, target_id,
       before_data::text as before_data, after_data::text as after_data,
       correlation_id, created_at
from governance.audit_log
where target_type = #{targetType}
and target_id = #{targetId}
order by created_at desc, id desc
limit #{limit}
